 * BBCode-to-HTML converter.
 *
 * Architecture: a real tokenizer produces a flat token stream
 * (text / open / close / item / raw), and a stack-driven renderer turns
 * tokens into HTML. No regex soup beyond small tag-shape matches in the
 * scanner itself.
 *
 * Nesting / error-handling rules (normative):
 *
 * 1. AUTO-CLOSE RULE: when an end tag matches a tag deeper in the stack,
 *    every tag pushed *after* it is implicitly closed first, and those
 *    tags are NOT reopened afterwards. Example:
 *        [b][i]x[/b]y   =>   <b><i>x</i></b>y
 *    (`y` is NOT bold or italic; the implicit `</i>` happened right
 *    before the explicit `</b>`.)
 *
 * 2. UNKNOWN TAGS render as literal (escaped) text: [foo]bar[/foo]
 *    stays "[foo]bar[/foo]" in the output, HTML-escaped.
 *
 * 3. UNCLOSED-TAG FALLBACK: a known end tag with no matching open tag on
 *    the stack renders as literal text ("[/b]" alone => "[/b]"). Any tag
 *    still open at end of input is likewise unwound as literal text,
 *    keeping its already-rendered children: "[b]hi" => "[b]hi".
 *
 * 4. [code] CONTENT IS RAW: the tokenizer swallows everything up to the
 *    matching [/code] as a single raw token. Inner BBCode is ignored and
 *    all characters are HTML-escaped at render time. An unterminated
 *    [code] falls back to rule 3 (the "[code]" itself becomes literal
 *    text and the remainder is parsed normally — still safely escaped).
 *
 * 5. URL SCHEME ALLOWLIST: [url=target] only accepts `http:`, `https:`,
 *    `mailto:` schemes, or relative URLs with no scheme at all.
 *    Anything else (javascript:, data:, ...) makes the whole tag render
 *    as literal escaped text.
 */

// ---------------------------------------------------------------------------
// Escaping
// ---------------------------------------------------------------------------

export function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

// ---------------------------------------------------------------------------
// Tokenizer
// ---------------------------------------------------------------------------

type Token =
  | { type: "text"; value: string }
  /** raw = already-final content (code bodies); must still be escaped at render */
  | { type: "raw"; value: string }
  | { type: "open"; name: string; attr?: string; source: string }
  | { type: "close"; name: string; source: string }
  | { type: "item"; source: string }; // [*]

const KNOWN_TAGS = new Set(["b", "i", "u", "url", "quote", "code", "list"]);
/** [*] uses name "*" internally */
const ITEM_TAG = "*";

const OPEN_RE = /^\[([a-zA-Z*]+)(?:=([^\]]*))?\]/;
const CLOSE_RE = /^\[\/([a-zA-Z*]+)\]/;

export function tokenize(src: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  let textStart = 0;

  const flushText = (end: number) => {
    if (end > textStart) tokens.push({ type: "text", value: src.slice(textStart, end) });
  };

  outer: while (i < src.length) {
    // ---- [code] special case: swallow raw body --------------------------
    if (/^\[code\]/i.test(src.slice(i))) {
      flushText(i);
      const openSource = src.slice(i, i + 6);
      tokens.push({ type: "open", name: "code", source: openSource });
      i += 6;
      textStart = i;
      const closeIdx = src.toLowerCase().indexOf("[/code]", i);
      if (closeIdx === -1) {
        // Unterminated [code]: rule 3 fallback — the open tag itself was
        // already emitted as a token and the rest parses normally.
        continue outer;
      }
      if (closeIdx > i) tokens.push({ type: "raw", value: src.slice(i, closeIdx) });
      tokens.push({ type: "close", name: "code", source: src.slice(closeIdx, closeIdx + 7) });
      i = closeIdx + 7;
      textStart = i;
      continue outer;
    }

    if (src[i] !== "[") {
      i++;
      continue outer;
    }

    // ---- well-formed tag shapes -----------------------------------------
    const rest = src.slice(i);
    const closeMatch = CLOSE_RE.exec(rest);
    if (closeMatch) {
      const name = closeMatch[1].toLowerCase();
      if (KNOWN_TAGS.has(name)) {
        flushText(i);
        tokens.push({ type: "close", name, source: closeMatch[0] });
        i += closeMatch[0].length;
        textStart = i;
        continue outer;
      }
      // unknown close tag -> literal text, fall through
    }

    const openMatch = OPEN_RE.exec(rest);
    if (openMatch && KNOWN_TAGS.has(openMatch[1].toLowerCase())) {
      flushText(i);
      const name = openMatch[1].toLowerCase();
      if (name === ITEM_TAG) {
        tokens.push({ type: "item", source: openMatch[0] });
      } else {
        tokens.push({
          type: "open",
          name,
          attr: openMatch[2],
          source: openMatch[0],
        });
      }
      i += openMatch[0].length;
      textStart = i;
      continue outer;
    }

    // ---- anything else is plain text -------------------------------------
    i++;
  }

  flushText(src.length);
  return tokens;
}

// ---------------------------------------------------------------------------
// Renderer (stack machine)
// ---------------------------------------------------------------------------

interface Frame {
  name: string;
  attr?: string;
  children: string[];
  /** list frames embed this sentinel between items */
  isList: boolean;
}

const ITEM_SENTINEL = "\u0000";

const WRAPPERS: Record<string, string> = {
  b: "b",
  i: "i",
  u: "u",
};

const ALLOWED_SCHEMES = ["http:", "https:", "mailto:"];

/**
 * Scheme allowlist, sanitizer-style. Accepts http:, https:, mailto:, and
 * scheme-less relative URLs. Everything else is rejected.
 */
export function isSafeUrl(target: string): boolean {
  const trimmed = target.trim();
  if (trimmed === "") return false;
  const colon = trimmed.indexOf(":");
  if (colon === -1) return true; // relative URL, no scheme
  if (trimmed.indexOf("/") !== -1 && trimmed.indexOf("/") < colon) return true;
  const scheme = trimmed.slice(0, colon + 1).toLowerCase();
  return ALLOWED_SCHEMES.includes(scheme);
}

function finalize(frame: Frame): string {
  const inner =
    frame.name === "list"
      ? frame.children.join("")
      : frame.children.join("");

  switch (frame.name) {
    case "code":
      return `<pre><code>${inner}</code></pre>`;
    case "list": {
      const items = inner.split(ITEM_SENTINEL).slice(1);
      return `<ul>${items.map((it) => `<li>${it}</li>`).join("")}</ul>`;
    }
    case "url":
      return `<a href="${escapeHtml(frame.attr ?? "")}">${inner}</a>`;
    case "quote":
      return frame.attr !== undefined
        ? `<blockquote data-author="${escapeHtml(frame.attr)}">${inner}</blockquote>`
        : `<blockquote>${inner}</blockquote>`;
    default: {
      const wrapper = WRAPPERS[frame.name];
      /* istanbul ignore if -- unreachable for known tags */
      if (!wrapper) return inner;
      return `<${wrapper}>${inner}</${wrapper}>`;
    }
  }
}

/** Unwind one still-open frame at EOF: literal tag text + kept children. */
function unwindAsLiteral(frame: Frame): string {
  let inner = frame.children.join("");
  if (frame.isList) inner = inner.split(ITEM_SENTINEL).join("[*]");
  return frame.source + inner;
}

export function render(src: string): string {
  const tokens = tokenize(src);
  const root: Frame = { name: "#root", children: [], isList: false };
  const stack: Frame[] = [root];

  const push = (frame: Frame) => stack.push(frame);

  for (const tok of tokens) {
    const top = stack[stack.length - 1];

    switch (tok.type) {
      case "text":
      case "raw":
        top.children.push(escapeHtml(tok.value));
        break;

      case "item": {
        if (top.isList) {
          top.children.push(ITEM_SENTINEL);
        } else {
          top.children.push(escapeHtml(tok.source)); // "[*]"
        }
        break;
      }

      case "open": {
        if (tok.name === "url") {
          const target = tok.attr ?? "";
          if (!isSafeUrl(target)) {
            // javascript: etc -> whole tag becomes plain (escaped) text
            top.children.push(escapeHtml(tok.source));
            break;
          }
          push({ name: "url", attr: target, children: [], isList: false });
          break;
        }
        if (
          tok.name === "code" ||
          tok.name === "quote" ||
          tok.name === "list" ||
          tok.name in WRAPPERS
        ) {
          push({
            name: tok.name,
            attr: tok.attr,
            children: [],
            isList: tok.name === "list",
          });
          break;
        }
        /* istanbul ignore next -- tokenizer only emits known tags */
        top.children.push(escapeHtml(tok.source));
        break;
      }

      case "close": {
        // Find the nearest matching open frame.
        let depth = -1;
        for (let d = stack.length - 1; d >= 1; d--) {
          if (stack[d].name === tok.name) {
            depth = d;
            break;
          }
        }

        if (depth === -1) {
          // No opener anywhere: literal text (rule 3).
          top.children.push(escapeHtml(tok.source));
          break;
        }

        // Auto-close rule: pop everything above the match first; the
        // popped tags are finalized but NOT reopened.
        while (stack.length > depth + 1) {
          const frame = stack.pop()!;
          stack[stack.length - 1].children.push(finalize(frame));
        }
        break;
      }
    }
  }

  // EOF: any frames left open render as literal text (rule 3).
  while (stack.length > 1) {
    const frame = stack.pop()!;
    stack[stack.length - 1].children.push(unwindAsLiteral(frame));
  }

  return root.children.join("");
}

export default render;
