result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/bbcode/tests/index.test.ts", "content": "import { describe, expect, it } from "vitest";
import { escapeHtml, isSafeUrl, render, tokenize } from "../src/index.js";

describe("basic tags", () => {
  it("renders b / i / u", () => {
    expect(render("[b]bold[/b]")).toBe("<b>bold</b>");
    expect(render("[i]ital[/i]")).toBe("<i>ital</i>");
    expect(render("[u]under[/u]")).toBe("<u>under</u>");
  });

  it("escapes HTML in text", () => {
    expect(render("[b]<script>alert('x')</script>[/b]"))
      .toBe("<b>&lt;script&gt;alert(&#39;x&#39;)&lt;/script&gt;</b>");
  });
});

describe("nesting auto-close", () => {
  it("auto-closes inner tag before an outer end tag, reopening nothing", () => {
    // The documented rule: [/b] closes [i] implicitly first; nothing is
    // reopened, so "y" is neither bold nor italic.
    expect(render("[b][i]x[/b]y")).toBe("<b><i>x</i></b>y");
  });

  it("three-deep auto-close chain", () => {
    // [u] and [i] both sit above [b]; both close before </b>, unreopened.
    expect(render("[b][u][i]x[/b]y[/i][/u]"))
      .toBe("<b><u><i>x</i></u></b>[i]y[/i]");
  });

  it("proper nesting still works normally", () => {
    expect(render("[b][i]x[/i][/b]")).toBe("<b><i>x</i></b>");
  });
});

describe("code block literalness", () => {
  it("escapes everything and ignores inner bbcode", () => {
    expect(render("[code][b]not bold[/b] <html> & \"quotes\"[/code]"))
      .toBe("<pre><code>[b]not bold[/b] &lt;html&gt; &amp; &quot;quotes&quot;</code></pre>");
  });

  it("does not treat [*] or other tags inside code as markup", () => {
    expect(render("[code][list][*]a[/list][/code]"))
      .toBe("<pre><code>[list][*]a[/list]</code></pre>");
  });

  it("unterminated code falls back to literal open tag, rest escaped", () => {
    expect(render("[code][b]x")).toBe("[code]<b>x</b>");
  });
});

describe("url scheme allowlist", () => {
  it.each([
    ["http://example.com"],
    ["https://example.com/a?b=c"],
    ["mailto:user@example.com"],
    ["/relative/path"],
    ["page.html#frag"],
  ])("allows %s", (target) => {
    expect(render(`[url=${target}]click[/url]`))
      .toBe(`<a href="${escapeHtml(target)}">click</a>`);
  });

  it("rejects javascript: and renders the whole tag as plain text", () => {
    expect(render("[url=javascript:alert(1)]click[/url]"))
      .toBe("[url=javascript:alert(1)]click[/url]");
  });

  it("rejects data: URLs too", () => {
    expect(render("[url=data:text/html,<b>x</b>]y[/url]"))
      .toBe("[url=data:text/html,&lt;b&gt;x&lt;/b&gt;]y[/url]");
  });

  it("isSafeUrl unit checks", () => {
    expect(isSafeUrl("JavaScript:alert(1)")).toBe(false);
    expect(isSafeUrl("vbscript:x")).toBe(false);
    expect(isSafeUrl("HTTPS://x")).toBe(true);
    expect(isSafeUrl("MAILTO:a@b")).toBe(true);
    expect(isSafeUrl("foo/bar:baz")).toBe(true); // slash before colon = relative
    expect(isSafeUrl("")).toBe(false);
  });
});

describe("quote", () => {
  it("renders author attribute, escaped", () => {
    expect(render('[quote="Bob & <co>"]hi[/quote]'))
      .toBe('<blockquote data-author="&quot;Bob &amp; &lt;co&gt;&quot;">hi</blockquote>');
  });

  it("plain quote has no attribute", () => {
    expect(render("[quote]hi[/quote]")).toBe("<blockquote>hi</blockquote>");
  });
